//! The host's round trip over a workbook Excel saved with dynamic arrays, legacy arrays, names
//! and a table (calc-doc's `tests/fixtures/cdoc_m1_2/d1.saved.xlsx`).
//!
//! - dc-ndi (D1): open, edit, recalculate, save with the calculated values as cached values, and
//!   the cells that read a removed array's area recalculated.
//! - dc-35p (D2): the session skins drive ([`calc_host::HostSession`]): cell entries, multi-cell
//!   edits, undo and redo, the calculation mode, the selection and subscriptions with their
//!   deltas, the intent log's replay, and the M1 proof: open, edit, undo, recalculate, save and
//!   reopen.

// Case names are fixed identities of the form `<bead>__<case>`.
#![allow(non_snake_case)]

#[path = "../../calc-engine/tests/fixtures/seven_cell_async.rs"]
mod async_provider;
mod contract_support;
#[path = "../../calc-doc/tests/cdoc_m1_1_support/mod.rs"]
mod existing_wire_support;
#[path = "../../calc-engine/tests/fixtures/seven_cell.rs"]
mod seven_cell;

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
fn dc_971p__format_cells_is_atomic_undoable_and_round_trips_styles() {
    use calc_host::{BorderPatch, FormatPatch, WorkbookCommand};
    for bytes in [
        calc_host::blank_package(),
        include_bytes!("fixtures/dc_09v/formats.xlsx").to_vec(),
    ] {
        let mut book = session(&bytes);
        let s = book.host().sheets()[0].id();
        let a = at(s, "A1");
        let b = at(s, "B2");
        let original = book.host().styles().clone();
        let old_a = book.host().cell_style(a);
        let old_b = book.host().cell_style(b);
        let values = [
            book.host().model().cell(a).cloned(),
            book.host().model().cell(b).cloned(),
        ];
        let patch = FormatPatch {
            number_format: Some("0.0000 \"units\"".into()),
            horizontal: Some("right".into()),
            vertical: Some("center".into()),
            wrap: Some(true),
            shrink: Some(true),
            rotation: Some(-30),
            indent: Some(2),
            font_name: Some("Arial".into()),
            font_size: Some("18".into()),
            bold: Some(true),
            italic: Some(true),
            underline: Some(true),
            underline_style: None,
            strike: Some(true),
            font_color: Some("#123456".into()),
            fill: Some("#ffeedd".into()),
            borders: Some(BorderPatch {
                left: true,
                right: true,
                top: true,
                bottom: true,
                style: "double".into(),
                color: "#ff0000".into(),
            }),
        };
        let areas = vec![GridArea::cell(a), GridArea::cell(b)];
        let receipt = book.dispatch(SkinIntent::Command(WorkbookCommand::FormatCells {
            areas: areas.clone(),
            patch: patch.clone(),
        }));
        assert!(receipt.accepted(), "{:?}", receipt.error);
        assert_eq!(book.host().model().cell(a).cloned(), values[0]);
        assert_eq!(book.host().model().cell(b).cloned(), values[1]);
        let after = book.host().styles().clone();
        assert!(after.fonts.starts_with(&original.fonts));
        assert!(after.cell_formats.starts_with(&original.cell_formats));
        let authored = [book.host().cell_style(a), book.host().cell_style(b)];
        assert!(book.host().cell_alignment(a).unwrap().shrink_to_fit);
        assert!(book.dispatch(SkinIntent::Undo).accepted());
        assert_eq!(book.host().styles(), &original);
        assert_eq!(book.host().cell_style(a), old_a);
        assert_eq!(book.host().cell_style(b), old_b);
        assert!(book.dispatch(SkinIntent::Redo).accepted());
        assert_eq!(book.host().styles(), &after);
        let revision = book.host().revision();
        let refusal = book.dispatch(SkinIntent::Command(WorkbookCommand::FormatCells {
            areas,
            patch: FormatPatch {
                font_size: Some("NaN".into()),
                ..Default::default()
            },
        }));
        assert!(!refusal.accepted());
        assert_eq!(book.host().revision(), revision);
        assert_eq!(book.host().styles(), &after);
        let mut saved = Vec::new();
        book.save(&SavePolicy::default(), &mut saved).unwrap();
        let reopened = open(&saved);
        let r = reopened.sheets()[0].id();
        assert_eq!(reopened.styles().fonts, after.fonts);
        assert_eq!(reopened.styles().fills, after.fills);
        assert_eq!(reopened.styles().borders, after.borders);
        assert_eq!(reopened.styles().cell_formats, after.cell_formats);
        assert_eq!(reopened.styles().number_formats, after.number_formats);
        for (address, index) in ["A1", "B2"].into_iter().zip(authored) {
            assert_eq!(reopened.cell_style(at(r, address)), index);
            assert!(
                reopened
                    .cell_alignment(at(r, address))
                    .unwrap()
                    .shrink_to_fit
            );
            assert_eq!(
                reopened.number_format(at(r, address)),
                Some("0.0000 \"units\"")
            );
        }
    }
}

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
fn dc_971p__copied_formats_restore_definitions_after_history_branches() {
    use calc_host::{
        CopySnapshot, FormatPatch, PasteMode, PasteSource, WorkbookCommand, prepare_paste,
    };
    let mut book = session(&calc_host::blank_package());
    let sheet = book.host().sheets()[0].id();
    let source = GridArea::cell(at(sheet, "A1"));
    let target = GridArea::cell(at(sheet, "B1"));
    assert!(enter(&mut book, source.first(), "17").accepted());
    let format = |book: &mut HostSession, area, fill: &str| {
        assert!(
            book.dispatch(SkinIntent::Command(WorkbookCommand::FormatCells {
                areas: vec![area],
                patch: FormatPatch {
                    fill: Some(fill.into()),
                    number_format: Some(format!("0.00 \"{fill}\"")),
                    font_name: Some("monospace".into()),
                    font_size: Some(if fill == "#ff0000" { "18" } else { "12" }.into()),
                    ..Default::default()
                },
            }))
            .accepted()
        );
    };
    format(&mut book, source, "#ff0000");
    let copied_style = book.host().cell_style(source.first());
    let snapshot = CopySnapshot::capture(book.host(), source).unwrap();
    let mut foreign = session(&calc_host::blank_package());
    let foreign_sheet = foreign.host().sheets()[0].id();
    assert_eq!(foreign_sheet, sheet);
    format(
        &mut foreign,
        GridArea::cell(at(foreign_sheet, "A1")),
        "#ff0000",
    );
    assert_eq!(foreign.host().styles(), book.host().styles());
    assert!(
        prepare_paste(
            foreign.host(),
            PasteSource::Snapshot {
                snapshot: &snapshot,
                cut: false
            },
            GridArea::cell(at(foreign_sheet, "B1")),
            PasteMode::Formats
        )
        .is_err(),
        "equal parsed styles cannot establish another workbook's raw-source lineage"
    );
    format(&mut book, GridArea::cell(at(sheet, "C1")), "#00ff00");
    let prepare = |book: &HostSession, mode| {
        prepare_paste(
            book.host(),
            PasteSource::Snapshot {
                snapshot: &snapshot,
                cut: false,
            },
            target,
            mode,
        )
    };
    assert!(
        prepare(&book, PasteMode::Formats).is_ok(),
        "appending styles retains captured indices"
    );
    assert!(book.dispatch(SkinIntent::Undo).accepted());
    assert!(book.dispatch(SkinIntent::Undo).accepted());
    assert!(
        prepare(&book, PasteMode::Formats).is_ok(),
        "captured styles are restored after Undo"
    );
    assert!(book.dispatch(SkinIntent::Redo).accepted());
    assert!(
        prepare(&book, PasteMode::Formats).is_ok(),
        "Redo restores captured definitions"
    );
    assert!(book.dispatch(SkinIntent::Undo).accepted());
    format(&mut book, source, "#0000ff");
    assert_eq!(
        book.host().cell_style(source.first()),
        copied_style,
        "the new history branch reuses the old index"
    );
    let blue = book.host().styles().clone();
    let fill = |host: &calc_host::HostState, cell| {
        let table = host.styles();
        let xf = &table.cell_formats[host.cell_style(cell) as usize];
        table.fills[xf.fill_id.unwrap() as usize]
            .fg_color
            .as_ref()
            .unwrap()
            .rgb
            .clone()
    };
    for mode in [PasteMode::All, PasteMode::Formats] {
        let plan = prepare(&book, mode).unwrap();
        assert!(
            book.dispatch(SkinIntent::Command(WorkbookCommand::Paste(plan)))
                .accepted()
        );
        assert_eq!(
            fill(book.host(), source.first()).as_deref(),
            Some("FF0000FF")
        );
        assert_eq!(
            fill(book.host(), target.first()).as_deref(),
            Some("FFFF0000")
        );
        assert_ne!(
            book.host().cell_style(source.first()),
            book.host().cell_style(target.first())
        );
        let mut saved = Vec::new();
        book.save(&SavePolicy::default(), &mut saved).unwrap();
        let reopened = session(&saved);
        let sheet = reopened.host().sheets()[0].id();
        assert_eq!(
            fill(reopened.host(), at(sheet, "A1")).as_deref(),
            Some("FF0000FF")
        );
        assert_eq!(
            fill(reopened.host(), at(sheet, "B1")).as_deref(),
            Some("FFFF0000")
        );
        let styles = book.host().styles().clone();
        assert!(book.dispatch(SkinIntent::Undo).accepted());
        assert_eq!(book.host().styles(), &blue);
        assert!(book.host().model().cell(target.first()).is_none());
        assert!(book.dispatch(SkinIntent::Redo).accepted());
        assert_eq!(book.host().styles(), &styles);
        assert_eq!(
            fill(book.host(), target.first()).as_deref(),
            Some("FFFF0000")
        );
        assert!(book.dispatch(SkinIntent::Undo).accepted());
    }
    assert!(
        snapshot
            .fill_edits(book.host(), target, false, false)
            .is_ok()
    );
    assert!(prepare(&book, PasteMode::Formulas).is_ok());
    let values = prepare(&book, PasteMode::Values).unwrap();
    assert!(
        book.dispatch(SkinIntent::Command(WorkbookCommand::Paste(values)))
            .accepted()
    );
    assert_eq!(
        book.host().model().cell(target.first()),
        Some(&number(17.0))
    );
    assert_eq!(book.host().cell_style(target.first()), 0);
}

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
fn dc_971p__clipboard_restoration_preserves_distinct_imported_style_sources() {
    use calc_host::{
        CopySnapshot, FormatPatch, PasteMode, PasteSource, WorkbookCommand as C, prepare_paste,
    };
    let bytes = package_with_part("xl/styles.xml", |xml| {
        xml.replacen("<styleSheet ", "<styleSheet xmlns:v=\"urn:clipboard\" ",1)
            .replacen("<fonts", r#"<numFmts count="2"><numFmt numFmtId="164" formatCode="0.00" v:keep="first"/><numFmt numFmtId="165" formatCode="0.00" v:keep="second"/></numFmts><fonts"#,1)
            .replacen("<name val=\"Calibri\"", "<name v:keep=\"font\" val=\"Calibri\"",1)
            .replacen("<cellXfs count=\"1\"", "<cellXfs count=\"2\"",1)
            .replacen("</cellXfs>", r#"<xf numFmtId="165" fontId="0" fillId="0" borderId="0" xfId="0" v:keep="xf"/></cellXfs>"#,1)
    });
    let bytes = package_with_part_from(&bytes, "xl/worksheets/sheet1.xml", |xml| {
        xml.replace(
            "<sheetData/>",
            r#"<sheetData><row r="1"><c r="A1" s="1"><v>3</v></c></row></sheetData>"#,
        )
    });
    let mut book = session(&bytes);
    let sheet = book.host().sheets()[0].id();
    let source = GridArea::cell(at(sheet, "A1"));
    let target = GridArea::cell(at(sheet, "B1"));
    let style = |book: &mut HostSession, bold| {
        assert!(
            book.dispatch(SkinIntent::Command(C::FormatCells {
                areas: vec![source],
                patch: FormatPatch {
                    bold: Some(bold),
                    italic: (!bold).then_some(true),
                    ..Default::default()
                }
            }))
            .accepted()
        )
    };
    style(&mut book, true);
    let snapshot = CopySnapshot::capture(book.host(), source).unwrap();
    assert!(book.dispatch(SkinIntent::Undo).accepted());
    style(&mut book, false);
    let plan = prepare_paste(
        book.host(),
        PasteSource::Snapshot {
            snapshot: &snapshot,
            cut: false,
        },
        target,
        PasteMode::Formats,
    )
    .unwrap();
    assert!(
        book.dispatch(SkinIntent::Command(C::Paste(plan)))
            .accepted()
    );
    let table = book.host().styles();
    let xf = &table.cell_formats[book.host().cell_style(target.first()) as usize];
    assert_eq!(xf.number_format_id, Some(165));
    assert!(table.fonts[xf.font_id.unwrap() as usize].bold);
    let mut saved = Vec::new();
    book.save(&SavePolicy::default(), &mut saved).unwrap();
    let xml = part_text(&saved, "xl/styles.xml");
    assert!(xml.contains(r#"v:keep="first""#));
    assert!(xml.contains(r#"v:keep="second""#));
    assert!(xml.matches(r#"v:keep="xf""#).count() >= 3, "{xml}");
    assert!(xml.matches(r#"v:keep="font""#).count() >= 2, "{xml}");
    let reopened = session(&saved);
    let s = reopened.host().sheets()[0].id();
    let table = reopened.host().styles();
    let xf = &table.cell_formats[reopened.host().cell_style(at(s, "B1")) as usize];
    assert_eq!(xf.number_format_id, Some(165));
    assert!(table.fonts[xf.font_id.unwrap() as usize].bold);
}

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
fn contract_scoped_cut_and_cell_shifts_follow_survivors_through_undo_redo() {
    use calc_engine::contract::{CalcEvent, CalcScope};
    let mut book = session(&calc_host::blank_package());
    let calc = book.host().sheets()[0].id();
    assert!(
        book.dispatch(SkinIntent::SetCalcMode(CalcMode::Manual))
            .accepted()
    );
    for (address, text) in [
        ("Z1", "=1+1"),
        ("Z2", "=2+2"),
        ("Z3", "=3+3"),
        ("AB1", "=99"),
    ] {
        assert!(enter(&mut book, at(calc, address), text).accepted());
    }
    let source = GridArea::new(at(calc, "Z1"), at(calc, "Z3")).unwrap();
    book.set_calculation_budget(WorkBudget::evaluations(1));
    assert!(
        book.dispatch(SkinIntent::CalculateRange {
            areas: vec![source]
        })
        .accepted()
    );
    assert!(book.has_pending_calculation());
    book.take_calculation_events();
    assert!(
        book.dispatch(SkinIntent::Copy {
            from: source,
            to: GridArea::cell(at(calc, "AA1")),
            cut: true
        })
        .accepted()
    );
    assert!(book.dispatch(SkinIntent::Undo).accepted());
    assert!(book.dispatch(SkinIntent::Redo).accepted());
    assert!(
        book.dispatch(SkinIntent::Command(
            calc_host::WorkbookCommand::ShiftCells {
                area: GridArea::cell(at(calc, "AA2")),
                down: true,
                insert: true
            }
        ))
        .accepted()
    );
    for _ in 0..16 {
        if !book.has_pending_calculation() {
            break;
        }
        book.advance_calculation();
    }
    assert!(!book.has_pending_calculation());
    let expected = CalcScope::Range(vec![
        GridArea::new(at(calc, "AA1"), at(calc, "AA4")).unwrap(),
    ]);
    let events = book.take_calculation_events();
    assert!(
        events
            .iter()
            .any(|event| matches!(event, CalcEvent::Admitted(a) if a.scope == expected))
    );
    assert!(events.iter().any(|event| matches!(event, CalcEvent::Completed(c) if c.scope == expected && c.coverage.required == 3 && c.coverage.calculated == 3)));
    for (address, value) in [("AA1", 2.0), ("AA3", 4.0), ("AA4", 6.0)] {
        assert_eq!(
            calculated(book.host(), at(calc, address)),
            Some(CalcValue::number(value))
        );
    }
    for address in ["Z1", "Z2", "Z3", "AA2", "AB1"] {
        assert!(
            calculated(book.host(), at(calc, address)).is_none(),
            "scope did not widen to {address}"
        );
    }
}

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
fn contract_cancel_is_terminal_and_advance_creates_no_history() {
    use calc_engine::contract::{CalcEvent, CompletionOutcome};
    let mut book = session(&fixture());
    let calc = sheet(book.host(), "Calc");
    book.take_calculation_events();
    book.set_calculation_budget(WorkBudget::evaluations(1));
    let receipt = book.dispatch(SkinIntent::Edit {
        edits: vec![
            CellEdit::Set {
                at: at(calc, "Z1"),
                input: formula("2+1"),
            },
            CellEdit::Set {
                at: at(calc, "Z2"),
                input: formula("Z1*2"),
            },
            CellEdit::Set {
                at: at(calc, "Z3"),
                input: formula("Z2*2"),
            },
        ],
    });
    assert!(receipt.accepted());
    assert!(book.has_pending_calculation());
    let events = book.take_calculation_events();
    let admission = events
        .iter()
        .find_map(|event| {
            if let CalcEvent::Admitted(receipt) = event {
                Some(receipt)
            } else {
                None
            }
        })
        .unwrap();
    assert_eq!(admission.source.sequence, receipt.seq);
    let source = admission.source;
    let command = admission.command;
    let history = book.intent_log().len();
    let revision = book.host().revision();
    book.cancel_calculation();
    assert!(!book.has_pending_calculation());
    let terminal = book.take_calculation_events();
    assert_eq!(terminal.iter().filter(|event| matches!(event,CalcEvent::Completed(receipt)
        if receipt.command==command && receipt.outcome==CompletionOutcome::Cancelled && receipt.after_publication.is_none())).count(),1);
    assert_eq!(book.advance_calculation(), HostProgress::Cancelled);
    assert_eq!(book.advance_calculation(), HostProgress::Cancelled);
    assert!(book.take_calculation_events().is_empty());
    assert_eq!(book.intent_log().len(), history);
    assert_eq!(book.host().revision(), revision);
    book.dispatch(SkinIntent::Recalculate);
    for _ in 0..256 {
        if !book.has_pending_calculation() {
            break;
        }
        book.advance_calculation();
    }
    assert!(!book.has_pending_calculation());
    assert_eq!(
        calculated(book.host(), at(calc, "Z3")),
        Some(CalcValue::number(12.0))
    );
    assert!(
        !book
            .take_calculation_events()
            .iter()
            .any(|event| matches!(event,CalcEvent::Completed(receipt)
        if receipt.command==command && receipt.outcome==CompletionOutcome::Complete))
    );
    assert_ne!(source.sequence, 0);
}

