    #[cfg_attr(not(target_arch = "wasm32"), test)]
    #[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
    fn contract_p07_async_suffix_resumes_once_and_dependents_get_a_later_pass() {
        let (mut book, s, counts) = setup("=10+AsyncEcho(A1)+3");
        let first = token(&book);
        assert_eq!(counts.borrow().prefix, 1);
        assert_eq!(counts.borrow().suffix, 0);
        assert!(
            !book.has_pending_calculation(),
            "an external wait schedules no busy task"
        );
        for _ in 0..3 {
            assert!(matches!(
                book.advance_calculation(),
                HostProgress::Waiting { .. }
            ));
        }
        assert_eq!(
            counts.borrow().resumes,
            1,
            "polling never re-enters a parked provider"
        );
        assert_eq!(
            book.complete_async(&first, CalcValue::number(29.0)),
            D::Accepted
        );
        assert!(book.has_pending_calculation());
        assert_eq!(
            counts.borrow().suffix,
            0,
            "delivery itself runs no provider code"
        );
        assert_eq!(
            book.complete_async(&first, CalcValue::number(29.0)),
            D::Duplicate
        );
        assert_eq!(
            book.complete_async(&first, CalcValue::number(999.0)),
            D::Rejected(R::ConflictingDuplicate)
        );
        drain(&mut book);
        assert_eq!(
            calculated(book.host(), at(s, "B1")),
            Some(CalcValue::number(42.0))
        );
        assert_eq!(
            calculated(book.host(), at(s, "C1")),
            Some(CalcValue::number(84.0))
        );
        assert_eq!((counts.borrow().prefix, counts.borrow().suffix), (1, 1));
        let b = value(book.host(), at(s, "B1"));
        let c = value(book.host(), at(s, "C1"));
        let (
            ProjectedValue::Calculated { calculation: b, .. },
            ProjectedValue::Calculated { calculation: c, .. },
        ) = (b, c)
        else {
            panic!("calculated values")
        };
        assert_eq!(
            b.stamp().unwrap().reads.invocations[0].runtime,
            first.runtime
        );
        assert_eq!(b.stamp().unwrap().certification.pass, first.invocation.pass);
        assert_eq!(
            c.stamp().unwrap().certification.pass.reason,
            calc_engine::contract::PassReason::AsyncDependents
        );
        assert_eq!(
            book.complete_async(&first, CalcValue::number(29.0)),
            D::Duplicate
        );
    }

    #[cfg_attr(not(target_arch = "wasm32"), test)]
    #[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
    fn contract_p07_async_waits_retain_lazy_name_and_lambda_frames() {
        for (formula, name, expected) in [
            ("=IF(TRUE,AsyncEcho(A1),AsyncEcho(999))+2", None, 42.0),
            ("=IF(AsyncEcho(A1),40,99)+2", None, 42.0),
            ("=IFERROR(1/0,AsyncEcho(A1))+2", None, 42.0),
            ("=IFNA(NA(),AsyncEcho(A1))+2", None, 42.0),
            ("=CHOOSE(2,AsyncEcho(999),AsyncEcho(A1))+2", None, 42.0),
            ("=LET(x,1,IF(TRUE,AsyncEcho(A1)+x,999))+2", None, 43.0),
            ("=LAMBDA(x,IF(TRUE,AsyncEcho(x)+x,999))(A1)+2", None, 43.0),
            ("=AsyncName+2", Some("IF(TRUE,AsyncEcho($A$1),999)"), 42.0),
            (
                "=AsyncName(A1)+2",
                Some("LAMBDA(x,IF(TRUE,AsyncEcho(x)+x,999))"),
                43.0,
            ),
        ] {
            for budget in [1, usize::MAX] {
                let (mut book, s, counts) = setup_with_name(formula, name, budget);
                let first = token(&book);
                assert!(!book.has_pending_calculation(), "parked {formula}");
                for _ in 0..3 {
                    assert!(matches!(
                        book.advance_calculation(),
                        HostProgress::Waiting { .. }
                    ));
                }
                assert_eq!(counts.borrow().resumes, 1, "no provider polling: {formula}");
                assert_eq!(
                    book.complete_async(&first, CalcValue::number(40.0)),
                    D::Accepted
                );
                drain(&mut book);
                assert_eq!(
                    calculated(book.host(), at(s, "B1")),
                    Some(CalcValue::number(expected)),
                    "{formula}"
                );
                assert_eq!(
                    calculated(book.host(), at(s, "C1")),
                    Some(CalcValue::number(expected * 2.0)),
                    "{formula}"
                );
                assert_eq!(
                    (counts.borrow().prefix, counts.borrow().suffix),
                    (1, 1),
                    "{formula}"
                );
            }
        }
    }

    #[cfg_attr(not(target_arch = "wasm32"), test)]
    #[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
    fn contract_p07_helpers_retain_items_accumulators_and_nested_async_frames() {
        for (formula, calls, expected) in [
            ("=SUM(MAP({1;2},LAMBDA(x,AsyncEcho(x)+x)))", 2, 83.0),
            (
                "=REDUCE(10,{1;2},LAMBDA(acc,x,acc+AsyncEcho(x)+x))",
                2,
                93.0,
            ),
            (
                "=SUM(SCAN(10,{1;2},LAMBDA(acc,x,acc+AsyncEcho(x)+x)))",
                2,
                144.0,
            ),
            (
                "=SUM(BYROW({1,2;3,4},LAMBDA(row,SUM(row)+AsyncEcho(SUM(row)))))",
                2,
                90.0,
            ),
            (
                "=SUM(BYCOL({1,2;3,4},LAMBDA(col,SUM(col)+AsyncEcho(SUM(col)))))",
                2,
                90.0,
            ),
            ("=SUM(MAKEARRAY(2,1,LAMBDA(r,c,AsyncEcho(r)+r+c)))", 2, 85.0),
            (
                "=SUM(MAP({1;2},LAMBDA(x,SUM(MAP({3;4},LAMBDA(y,AsyncEcho(x+y)+x+y))))))",
                4,
                180.0,
            ),
        ] {
            for budget in [1, usize::MAX] {
                let (mut book, s, counts) = setup_with_name(formula, None, budget);
                let mut tokens = Vec::new();
                for ordinal in 0..calls {
                    let current = token(&book);
                    assert!(
                        tokens
                            .iter()
                            .all(|old: &AsyncToken| old.invocation != current.invocation)
                    );
                    tokens.push(current.clone());
                    let resumes = counts.borrow().resumes;
                    for _ in 0..3 {
                        assert!(matches!(
                            book.advance_calculation(),
                            HostProgress::Waiting { .. }
                        ));
                    }
                    assert_eq!(counts.borrow().resumes, resumes, "no polling {formula}");
                    assert_eq!(counts.borrow().prefix, ordinal + 1, "{formula}");
                    assert_eq!(counts.borrow().suffix, ordinal, "{formula}");
                    assert_eq!(
                        book.complete_async(&current, CalcValue::number(40.0)),
                        D::Accepted
                    );
                    for _ in 0..200 {
                        if !book.host().pending_async().is_empty()
                            || !book.has_pending_calculation()
                        {
                            break;
                        }
                        assert!(!matches!(
                            book.advance_calculation(),
                            HostProgress::Failed(_)
                        ));
                    }
                }
                drain(&mut book);
                assert_eq!(
                    calculated(book.host(), at(s, "B1")),
                    Some(CalcValue::number(expected)),
                    "{formula}"
                );
                assert_eq!(
                    calculated(book.host(), at(s, "C1")),
                    Some(CalcValue::number(expected * 2.0)),
                    "{formula}"
                );
                assert_eq!(
                    (counts.borrow().prefix, counts.borrow().suffix),
                    (calls, calls),
                    "{formula}"
                );
                assert_eq!(
                    book.complete_async(&tokens[0], CalcValue::number(40.0)),
                    D::Duplicate
                );
            }
        }
    }

    #[cfg_attr(not(target_arch = "wasm32"), test)]
    #[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
    fn contract_p07_post_effect_dependency_wait_retains_operands_and_invocation() {
        for formula in [
            "=AsyncEcho(A1)+INDIRECT(\"D1\")",
            "=SUM(MAP({1;2},LAMBDA(x,IF(x=1,AsyncEcho(A1),0)+INDIRECT(\"D1\"))))",
        ] {
            for budget in [1, usize::MAX] {
                let (mut book, s, counts) = configured(formula, None, budget);
                enter(&mut book, at(s, "D1"), "=A1*10");
                book.dispatch(SkinIntent::Recalculate);
                for _ in 0..200 {
                    if !book.host().pending_async().is_empty() {
                        break;
                    }
                    assert!(book.has_pending_calculation());
                    book.advance_calculation();
                }
                let current = token(&book);
                assert_eq!(
                    book.complete_async(&current, CalcValue::number(40.0)),
                    D::Accepted
                );
                drain(&mut book);
                let expected = if formula.contains("MAP") { 60.0 } else { 50.0 };
                assert_eq!(
                    calculated(book.host(), at(s, "B1")),
                    Some(CalcValue::number(expected)),
                    "{formula}"
                );
                assert_eq!(
                    calculated(book.host(), at(s, "C1")),
                    Some(CalcValue::number(expected * 2.0)),
                    "{formula}"
                );
                assert_eq!((counts.borrow().prefix, counts.borrow().suffix), (1, 1));
                let value = value(book.host(), at(s, "B1"));
                assert!(
                    matches!(value, ProjectedValue::Calculated { .. }),
                    "{value:?}"
                );
            }
        }
    }

    #[cfg_attr(not(target_arch = "wasm32"), test)]
    #[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
    fn contract_p07_two_nested_async_sites_keep_locals_and_distinct_tokens() {
        let (mut book, s, counts) =
            setup("=LET(x,AsyncEcho(A1),LAMBDA(y,IF(TRUE,AsyncEcho(y)+x,99))(x))+2");
        let first = token(&book);
        assert_eq!(
            book.complete_async(&first, CalcValue::number(20.0)),
            D::Accepted
        );
        drain(&mut book);
        let second = token(&book);
        assert_ne!(first.runtime, second.runtime);
        assert_ne!(first.invocation.call_site, second.invocation.call_site);
        assert_eq!(first.invocation.pass, second.invocation.pass);
        assert_eq!(
            book.complete_async(&first, CalcValue::number(20.0)),
            D::Duplicate
        );
        assert_eq!(
            book.complete_async(&second, CalcValue::number(20.0)),
            D::Accepted
        );
        drain(&mut book);
        assert_eq!(
            calculated(book.host(), at(s, "B1")),
            Some(CalcValue::number(42.0))
        );
        assert_eq!((counts.borrow().prefix, counts.borrow().suffix), (2, 2));
    }

