#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
fn dc_971p_40__rejected_candidate_does_not_call_live_user_function_providers() {
    use std::{cell::Cell, rc::Rc};
    #[derive(Debug)]
    struct Counter(Rc<Cell<u32>>);
    impl calc_fml::UserFunction for Counter {
        fn call(&self, _: &[calc_value::CalcValue]) -> Result<calc_value::CalcValue, String> {
            self.0.set(self.0.get() + 1);
            Ok(calc_value::CalcValue::number(1.))
        }
    }
    let bytes = package_with_part("xl/worksheets/sheet1.xml", |xml| {
        xml.replace("</worksheet>",r#"<dataValidations count="1"><dataValidation type="custom" showErrorMessage="1" sqref="A1"><formula1>A1&gt;0</formula1></dataValidation></dataValidations></worksheet>"#)
    });
    let mut book = session(&bytes);
    let s = book.host().sheets()[0].id();
    let calls = Rc::new(Cell::new(0));
    let mut functions = calc_fml::CallableTable::new();
    functions
        .register("ValidationCounter", Rc::new(Counter(calls.clone())))
        .unwrap();
    book.set_user_functions(functions);
    assert!(enter(&mut book, at(s, "Z1"), "=ValidationCounter()").accepted());
    calls.set(0);
    let revision = book.host().revision();
    let depth = book.history_depth();
    let input =
        calc_host::interpret_entry_in("-3", Some(&book.host().entry_environment())).unwrap();
    let failure = book
        .host()
        .check_entry(at(s, "A1"), input.as_ref())
        .unwrap_err();
    assert!(failure.title.contains("dc-971p.40"));
    assert!(
        !book
            .dispatch(SkinIntent::EnterCell {
                at: at(s, "A1"),
                text: "-3".into()
            })
            .accepted()
    );
    assert_eq!(calls.get(), 0);
    assert_eq!(book.host().revision(), revision);
    assert_eq!(book.history_depth(), depth);
}

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
fn dc_971p_40__deleting_rule_origin_rebases_surviving_cells_and_keeps_rules_when_notes_empty() {
    use calc_host::ValidationStatus;
    for areas in ["A1:A4", "A1 A3:A5"] {
        let bytes = package_with_part_from(
            &calc_host::blank_package(),
            "xl/worksheets/sheet1.xml",
            |xml| {
                xml.replace("</worksheet>",&format!(r#"<dataValidations count="1"><dataValidation type="custom" showErrorMessage="0" sqref="{areas}"><formula1>A1&gt;0</formula1></dataValidation></dataValidations></worksheet>"#))
            },
        );
        let mut book = session(&bytes);
        let s = book.host().sheets()[0].id();
        for (a, v) in [
            ("A1", "1"),
            ("A2", "2"),
            ("A3", "3"),
            ("A4", "4"),
            ("A5", "5"),
        ] {
            enter(&mut book, at(s, a), v);
        }
        assert!(
            book.dispatch(SkinIntent::EditAxis(
                AxisEdit::new(s, Axis::Rows, AxisChange::Delete, 1, 1).unwrap()
            ))
            .accepted()
        );
        let address = if areas.contains(' ') { "A2" } else { "A1" };
        assert_eq!(
            book.host().validation_status(at(s, address)),
            Some(ValidationStatus::Valid)
        );
        assert!(book.dispatch(SkinIntent::Undo).accepted());
        assert_eq!(
            book.host().validation_status(at(s, "A1")),
            Some(ValidationStatus::Valid)
        );
        assert!(book.dispatch(SkinIntent::Redo).accepted());
        let mut saved = Vec::new();
        book.save(&SavePolicy::default(), &mut saved).unwrap();
        let reopened = session(&saved);
        let rs = reopened.host().sheets()[0].id();
        assert_eq!(
            reopened.host().validation_status(at(rs, address)),
            Some(ValidationStatus::Valid)
        );
    }
    let original = include_bytes!("fixtures/d2/structural-base.xlsx");
    let bytes = package_with_part_from(original, "xl/worksheets/sheet1.xml", |xml| {
        xml.replace("</worksheet>",r#"<dataValidations count="1"><dataValidation type="whole" operator="between" showErrorMessage="1" sqref="Z10:Z12"><formula1>1</formula1><formula2>9</formula2></dataValidation></dataValidations></worksheet>"#)
    });
    let mut book = session(&bytes);
    let s = sheet(book.host(), "S");
    assert!(!book.host().model().definitions().review_notes(s).is_empty());
    enter(&mut book, at(s, "Z10"), "5");
    assert!(
        book.dispatch(SkinIntent::Edit {
            edits: vec![CellEdit::ConditionalRules {
                sheet: s,
                rules: vec![]
            }]
        })
        .accepted()
    );
    let revision = book.host().revision().get();
    assert!(
        book.dispatch(SkinIntent::Command(
            calc_host::WorkbookCommand::AutoFilter {
                sheet: s,
                revision,
                change: calc_host::FilterChange::Remove
            }
        ))
        .accepted()
    );
    let receipt = book.dispatch(SkinIntent::EditAxis(
        AxisEdit::new(s, Axis::Rows, AxisChange::Delete, 1, 8).unwrap(),
    ));
    assert!(receipt.accepted(), "{receipt:?}");
    assert!(book.host().model().definitions().review_notes(s).is_empty());
    assert_eq!(
        book.host().validation_status(at(s, "Z2")),
        Some(ValidationStatus::Valid)
    );
    let mut saved = Vec::new();
    book.save(&SavePolicy::default(), &mut saved).unwrap();
    let reopened = session(&saved);
    let rs = sheet(reopened.host(), "S");
    assert_eq!(
        reopened.host().validation_status(at(rs, "Z2")),
        Some(ValidationStatus::Valid)
    );
}

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
fn dc_971p_40__raw_validation_edits_refuse_bad_coordinates_and_source_attribute_changes() {
    let bytes = package_with_part("xl/worksheets/sheet1.xml", |xml| {
        xml.replace("</worksheet>",r#"<dataValidations count="1"><dataValidation type="whole" showErrorMessage="1" sqref="Z1"><formula1>1</formula1><formula2>9</formula2></dataValidation></dataValidations></worksheet>"#)
    });
    let mut book = session(&bytes);
    let s = book.host().sheets()[0].id();
    let old = book.host().model().definitions().validations(s).to_vec();
    let revision = book.host().revision();
    let depth = book.history_depth();
    for malformed in 0..3 {
        let mut rules = old.clone();
        if malformed == 0 {
            rules[0].areas = vec![(0, 1, 1, 1)];
        } else if malformed == 1 {
            rules[0].allow_blank = !rules[0].allow_blank;
            rules[0].show_error = false;
        } else {
            rules[0].formula2 = None;
        }
        assert!(
            !book
                .dispatch(SkinIntent::Edit {
                    edits: vec![CellEdit::Validations { sheet: s, rules }]
                })
                .accepted()
        );
        assert_eq!(book.host().revision(), revision);
        assert_eq!(book.history_depth(), depth);
        assert_eq!(book.host().model().definitions().validations(s), old);
    }
    let mut saved = Vec::new();
    book.save(&SavePolicy::default(), &mut saved).unwrap();
    let reopened = session(&saved);
    let rs = reopened.host().sheets()[0].id();
    let rule = &reopened.host().model().definitions().validations(rs)[0];
    assert!(!rule.allow_blank);
    assert!(rule.show_error);
}
fn review_action(
    book: &mut HostSession,
    at: CellKey,
    action: calc_host::ReviewAction,
) -> calc_host::IntentReceipt {
    book.dispatch(SkinIntent::Command(
        calc_host::WorkbookCommand::ReviewAction {
            at,
            revision: book.host().revision().get(),
            action,
        },
    ))
}

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
fn dc_971p_40__new_notes_partial_rich_text_and_imported_run_properties_round_trip() {
    use calc_host::{NoteStylePatch, ReviewAction as R};
    let mut book = session(&calc_host::blank_package());
    let s = book.host().sheets()[0].id();
    let a = at(s, "A1");
    let depth = book.history_depth();
    let receipt = review_action(
        &mut book,
        a,
        R::Create {
            parent: None,
            threaded: false,
            author: "Author & <Ω> _x0041_".into(),
            text: "A🧬 bold tail".into(),
            timestamp: String::new(),
        },
    );
    assert!(receipt.accepted(), "{receipt:?}");
    assert_eq!(book.history_depth().0, depth.0 + 1);
    assert!(
        review_action(
            &mut book,
            a,
            R::Format {
                index: 0,
                text: "A🧬 bold tail".into(),
                start: 4,
                end: 8,
                patch: NoteStylePatch {
                    bold: Some(true),
                    italic: Some(true),
                    color: Some("#123456".into()),
                    ..Default::default()
                }
            }
        )
        .accepted()
    );
    let note = &book.host().model().definitions().review_notes(s)[0];
    assert_eq!(note.spans.len(), 1);
    assert_eq!((note.spans[0].start, note.spans[0].end), (4, 8));
    assert!(note.spans[0].style.bold && note.spans[0].style.italic);
    let revision = book.host().revision();
    assert!(
        !review_action(
            &mut book,
            a,
            R::Format {
                index: 0,
                text: "A🧬 bold tail".into(),
                start: 2,
                end: 3,
                patch: NoteStylePatch {
                    underline: Some(true),
                    ..Default::default()
                }
            }
        )
        .accepted()
    );
    assert_eq!(book.host().revision(), revision);
    assert!(book.dispatch(SkinIntent::Undo).accepted());
    assert!(
        book.host().model().definitions().review_notes(s)[0]
            .spans
            .is_empty()
    );
    assert!(book.dispatch(SkinIntent::Redo).accepted());
    let mut saved = Vec::new();
    book.save(&SavePolicy::default(), &mut saved).unwrap();
    let mut reopened = session(&saved);
    let rs = reopened.host().sheets()[0].id();
    let note = &reopened.host().model().definitions().review_notes(rs)[0];
    assert_eq!(note.text, "A🧬 bold tail");
    assert_eq!(note.author, "Author & <Ω> _x0041_");
    assert!(note.style_at(4).bold);
    assert!(!note.style_at(3).bold);
    assert_eq!(note.style_at(4).color.as_deref(), Some("FF123456"));
    let part = note.source.as_ref().unwrap().part().to_owned();
    let comments = part_text(&saved, &part);
    assert!(comments.contains("<b") && comments.contains("<i") && comments.contains("123456"));
    assert!(part_text(&saved, "xl/worksheets/sheet1.xml").contains("legacyDrawing"));
    assert!(part_text(&saved, "xl/worksheets/_rels/sheet1.xml.rels").contains("vmlDrawing"));
    let note=comments.replace("</rPr>","<rFont val=\"Cambria\"/><charset val=\"1\"/><meta:flag xmlns:meta=\"urn:retained\" value=\"keep\"/></rPr>");
    let augmented = package_with_part_from(&saved, &part, |_| note.clone());
    reopened = session(&augmented);
    let rs = reopened.host().sheets()[0].id();
    assert!(
        review_action(
            &mut reopened,
            at(rs, "A1"),
            R::Edit {
                index: 0,
                text: "A🧬 bold appended tail".into()
            }
        )
        .accepted()
    );
    let mut saved = Vec::new();
    reopened.save(&SavePolicy::default(), &mut saved).unwrap();
    let xml = part_text(&saved, &part);
    for fragment in ["Cambria", "charset", "meta:flag", "keep"] {
        assert!(xml.contains(fragment), "{xml}");
    }
    let reopened = session(&saved);
    assert!(
        reopened
            .host()
            .model()
            .definitions()
            .review_notes(reopened.host().sheets()[0].id())[0]
            .style_at(4)
            .bold
    );
}

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
fn dc_971p_40__new_thread_replies_resolution_and_repeated_saves_retain_people_and_ids() {
    use calc_host::ReviewAction as R;
    let mut book = session(&calc_host::blank_package());
    let s = book.host().sheets()[0].id();
    let a = at(s, "C3");
    let create = |parent, author: &str, text: &str| R::Create {
        parent,
        threaded: true,
        author: author.into(),
        text: text.into(),
        timestamp: "2026-11-03T20:00:00.000Z".into(),
    };
    let receipt = review_action(&mut book, a, create(None, "Alice & Ω", "Root <text>"));
    assert!(receipt.accepted(), "{receipt:?}");
    let index = book.host().model().definitions().review_notes(s).len() as u32;
    assert!(review_action(&mut book, a, create(Some(0), "Bob", "Reply one")).accepted());
    assert!(review_action(&mut book, a, create(Some(index), "Alice & Ω", "Reply two")).accepted());
    assert!(
        review_action(
            &mut book,
            a,
            R::Resolve {
                index,
                resolved: true
            }
        )
        .accepted()
    );
    assert!(!review_action(&mut book, a, create(Some(0), "Bob", "Blocked reply")).accepted());
    assert!(
        review_action(
            &mut book,
            a,
            R::Resolve {
                index: 0,
                resolved: false
            }
        )
        .accepted()
    );
    let before = book.host().model().definitions().review_notes(s).to_vec();
    let ids = before
        .iter()
        .filter_map(|n| match &n.source {
            Some(calc_doc_model::ReviewSource::Thread { id, .. }) => Some(id.clone()),
            _ => None,
        })
        .collect::<Vec<_>>();
    let mut saved = Vec::new();
    book.save(&SavePolicy::default(), &mut saved).unwrap();
    let mut reopened = session(&saved);
    let rs = reopened.host().sheets()[0].id();
    let notes = reopened.host().model().definitions().review_notes(rs);
    assert_eq!(notes.iter().filter(|n| !n.compatibility).count(), 3);
    assert_eq!(notes.iter().filter(|n| n.compatibility).count(), 1);
    assert_eq!(
        notes
            .iter()
            .filter_map(|n| match &n.source {
                Some(calc_doc_model::ReviewSource::Thread { id, .. }) => Some(id.clone()),
                _ => None,
            })
            .collect::<Vec<_>>(),
        ids
    );
    assert!(
        notes
            .iter()
            .any(|n| n.author == "Alice & Ω" && n.text == "Reply two")
    );
    let root_index = notes
        .iter()
        .position(|n| {
            matches!(
                &n.source,
                Some(calc_doc_model::ReviewSource::Thread { parent: None, .. })
            )
        })
        .unwrap() as u32;
    let receipt = review_action(
        &mut reopened,
        at(rs, "C3"),
        R::Edit {
            index: root_index,
            text: "Edited root".into(),
        },
    );
    assert!(receipt.accepted(), "{receipt:?}");
    let mut twice = Vec::new();
    reopened.save(&SavePolicy::default(), &mut twice).unwrap();
    let last = session(&twice);
    let ls = last.host().sheets()[0].id();
    let notes = last.host().model().definitions().review_notes(ls);
    assert_eq!(notes.iter().filter(|n| !n.compatibility).count(), 3);
    assert_eq!(last.host().loaded().review_people().len(), 2);
    assert!(notes.iter().any(|n| n.compatibility
        && n.text.contains("Edited root")
        && n.text.contains("Reply two")));
    assert!(book.dispatch(SkinIntent::Undo).accepted());
}

#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
fn dc_971p_40__legacy_note_revision_ids_remain_unique_after_reopen_and_raw_forgeries_refuse() {
    use calc_host::ReviewAction as R;
    let mut book = session(&calc_host::blank_package());
    let s = book.host().sheets()[0].id();
    assert!(
        review_action(
            &mut book,
            at(s, "A1"),
            R::Create {
                parent: None,
                threaded: false,
                author: "A".into(),
                text: "First".into(),
                timestamp: String::new()
            }
        )
        .accepted()
    );
    let mut saved = Vec::new();
    book.save(&SavePolicy::default(), &mut saved).unwrap();
    let mut book = session(&saved);
    let s = book.host().sheets()[0].id();
    let first = book.host().model().definitions().review_notes(s)[0]
        .source
        .clone();
    assert!(
        review_action(
            &mut book,
            at(s, "B1"),
            R::Create {
                parent: None,
                threaded: false,
                author: "B".into(),
                text: "Second".into(),
                timestamp: String::new()
            }
        )
        .accepted()
    );
    let mut saved = Vec::new();
    book.save(&SavePolicy::default(), &mut saved).unwrap();
    let reopened = session(&saved);
    let rs = reopened.host().sheets()[0].id();
    let notes = reopened.host().model().definitions().review_notes(rs);
    let ids = notes
        .iter()
        .filter_map(|n| match &n.source {
            Some(calc_doc_model::ReviewSource::Note { uid, .. }) => uid.clone(),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(ids.len(), 2);
    assert_ne!(ids[0], ids[1]);
    assert!(
        matches!(first,Some(calc_doc_model::ReviewSource::Note{uid:Some(uid),..})if uid==ids[0])
    );
    let before = book.host().revision();
    let mut forged = book.host().model().definitions().review_notes(s).to_vec();
    if let Some(calc_doc_model::ReviewSource::NewNote { part, .. }) = &mut forged[1].source {
        *part = "xl/workbook.xml".into();
    } else {
        panic!("new note");
    }
    assert!(
        !book
            .dispatch(SkinIntent::Edit {
                edits: vec![CellEdit::ReviewNotes {
                    sheet: s,
                    notes: forged
                }]
            })
            .accepted()
    );
    assert_eq!(book.host().revision(), before);
}

